"topic-body\"></p>\n    </section>\n\n    <section class=\"facts\">\n      <span class=\"section-label\">THE FACTS</span>\n      <ul id=\"facts-list\"></ul>\n    </section>\n\n    <section class=\"related\" id=\"related-section\" hidden>\n      <span class=\"section-label\">KEEP EXPLORING</span>\n      <div class=\"chips\" id=\"related-chips\"></div>\n    </section>\n\n    <section class=\"cta-row\">\n      <button class=\"btn-primary\" id=\"cta-read\">Read more on getmasset.com</button>\n      <button class=\"btn-secondary\" id=\"cta-try\">Try Masset</button>\n    </section>\n\n    <footer class=\"footer\">\n      <span>Free from <a href=\"https://www.getmasset.com\" target=\"_blank\" rel=\"noopener\">Masset</a>, the home for your business content.</span>\n      <a class=\"footer-src\" href=\"https://github.com/BenMasset/masset-mcp-tools\" target=\"_blank\" rel=\"noopener\">Open source</a>\n    </footer>\n  </div>\n</body>\n</html>\n";
